package consensus

type RaftNode struct {
    currentTerm int64
    votedFor    string
    log         []LogEntry
    commitIndex int64
    lastApplied int64
    state       NodeState // Follower, Candidate, Leader
}

// PreVote protocol prevents disrupted nodes from forcing election
func (rn *RaftNode) HandlePreVote(req *PreVoteRequest) *PreVoteResponse {
    if req.Term > rn.currentTerm && req.LastLogIndex >= rn.getLastLogIndex() {
        return &PreVoteResponse{VoteGranted: true}
    }
    return &PreVoteResponse{VoteGranted: false}
}
